INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(94600, 'ruRU', 'Знаю... малость опоздал. Моя благоверная не больно обрадовалась, что я снова в бой пошёл после стольких-то лет. Говорит, мол, никому не нужен старый вояка.', '', 24330),
(94601, 'ruRU', 'Начнём-ка эту заварушку!', '', 24330),
(94602, 'ruRU', 'Щиты при мне, а клинок — к твоим услугам, командир!', '', 24330),
(94604, 'ruRU', 'Ты смеешь бросать вызов Легиону?', '', 24330),
(94605, 'ruRU', 'Щиты вверх! Никогда не сдавайтесь!', '', 24330),
(94606, 'ruRU', 'Ты спас меня! Я... я всё ещё слышу голоса. Прошу, не дай им забрать остальных.', '', 24330),
(94607, 'ruRU', 'Мне нехорошо. Как я здесь оказался? Что... что это за твари?', '', 24330),
(94608, 'ruRU', 'Король-бог уже вошёл в Чертоги Доблести. Пришло время завершить твои испытания и победить Привратника.', '', 24330),
(94609, 'ruRU', 'Отнеси меня сквозь бурю. Я готов сразиться с Привратником.', '', 24330),
(94610, 'ruRU', 'Эй, кажется, получилось!', '', 24330),
(94612, 'ruRU', 'Он не мерзкий! Просто... его неправильно понимают.', '', 24330),
(94613, 'ruRU', 'Пусть мой трофейный головной убор тебя не обманывает. Я на твоей стороне!', '', 24330),
(94614, 'ruRU', 'Шифр станет нашим!', '', 24330),
(94617, 'ruRU', 'Мы найдём шифр!', '', 24330),
(94618, 'ruRU', 'Одной лишь силой того, что ты ищешь, не добиться.', '', 24330),
(94619, 'ruRU', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-GRAND CHAMPIONS-ALLIANCE.blp:50:80|t$b[Граян Твердоплащ] Твоему вторжению конец, демон.', '', 24330),
(94620, 'ruRU', 'Но для начала хватит. Найди меня возле Хранилища Аграмара, и я испытаю твою силу.', '', 24330),
(94621, 'ruRU', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-GRAND CHAMPIONS-ALLIANCE.blp:50:80|t$b[Граян Твердоплащ] $p высвободил гнев Пеплосерда. В атаку!', '', 24330),
(94622, 'ruRU', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[Малгалор] Я сокрушу Опоры Созидания, а заодно и вас.', '', 24330),
(94623, 'ruRU', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[Малгалор] Вы зря тратите время, смертные.', '', 24330),
(94624, 'ruRU', 'Хватайте камни здоровья, герои!', '', 24330),
(94626, 'ruRU', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[Малгалор] Ваше жалкое оружие не пробьёт мою броню.', '', 24330),
(94627, 'ruRU', 'Ты сделал это! Я отнесу тебя обратно к порталу.', '', 24330),
(94628, 'ruRU', 'Отнеси меня обратно сквозь бурю. Я готов войти в Чертоги Доблести.', '', 24330),
(94630, 'ruRU', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[Малгалор] Этот мир сгорит. Слушай крики своих союзников, «защитник».', '', 24330),
(94633, 'ruRU', 'Будем надеяться, что ты прав.', '', 24330),
(94634, 'ruRU', 'Мой волк сегодня славно отужинает!', '', 24330),
(94636, 'ruRU', 'Один готов, осталось двое.', '', 24330),
(94637, 'ruRU', 'Ты заплатишь за это злодеяние. Легион бесконечен! ИНФЕРНАЛ.', '', 24330),
(94638, 'ruRU', 'Ещё один — и берег наш!', '', 24330),
(94639, 'ruRU', 'Хочешь столкнуться с мощью Легиона? Ха, прекрасно. Хозяин вознаградит меня за ваши души.', '', 24330);
